{#- Iraq Tax Invoice (DEMO) - bilingual Arabic / English, RTL. Amounts in the invoice currency (IQD: 3 decimals / Fils). -#}
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set customer_tax_id = doc.get("iraq_tax_id") or doc.tax_id -%}
{%- set company_tax_id = doc.get("company_iraq_tax_id") or company.get("iraq_tax_id") or doc.company_tax_id -%}
{%- set has_item_tax = doc.items and doc.items[0].meta.has_field("tax_rate") -%}
{#- Precision follows the invoice currency's number format (IQD "#,###.###" -> 3 decimals / Fils), regardless of the site-wide currency_precision setting. -#}
{%- set number_format = frappe.db.get_value("Currency", doc.currency, "number_format") or frappe.db.get_single_value("System Settings", "number_format") or "#,###.##" -%}
{#- Decimal places of the number format: the last separator is the decimal one unless it is the only kind of separator and is followed by a group of three (thousands only, e.g. "#.###"). -#}
{%- set nf_seps = number_format | replace("#", "") -%}
{%- set nf_tail = number_format.rsplit(nf_seps[-1], 1)[-1] if nf_seps else "" -%}
{%- set money_precision = (nf_tail | length) if nf_seps and (nf_seps[-1] != nf_seps[0] or (nf_tail | length) != 3) else 0 -%}
{%- macro money(value) -%}{{ frappe.utils.fmt_money(value, money_precision, doc.currency, number_format) }}{%- endmacro -%}
<style>
	.iq-invoice { direction: rtl; unicode-bidi: embed; font-family: "Noto Naskh Arabic", "Noto Sans Arabic", "Amiri", "Inter", Tahoma, sans-serif; color: #171717; }
	.iq-invoice .en { font-size: 0.85em; color: #6c7680; display: block; direction: ltr; }
	.iq-invoice .ar { font-weight: 600; }
	.iq-invoice h2 { text-align: center; margin: 0 0 4px 0; }
	.iq-invoice .subtitle { text-align: center; color: #6c7680; margin-bottom: 14px; }
	.iq-invoice table.parties, .iq-invoice table.items, .iq-invoice table.taxes, .iq-invoice table.totals { width: 100%; border-collapse: collapse; margin-top: 12px; }
	.iq-invoice table.parties td { vertical-align: top; width: 50%; padding: 6px 8px; border: 1px solid #d1d8dd; }
	.iq-invoice table.items th, .iq-invoice table.items td, .iq-invoice table.taxes th, .iq-invoice table.taxes td { border: 1px solid #d1d8dd; padding: 5px 6px; }
	.iq-invoice table.items th, .iq-invoice table.taxes th { background: #f3f3f3; text-align: center; }
	.iq-invoice td.num, .iq-invoice th.num { text-align: left; direction: ltr; white-space: nowrap; font-variant-numeric: tabular-nums; }
	.iq-invoice table.totals td { padding: 4px 8px; }
	.iq-invoice table.totals td.label { width: 60%; }
	.iq-invoice tr.grand td { font-weight: 700; border-top: 2px solid #171717; }
	.iq-invoice .in-words { margin-top: 10px; padding: 8px; border: 1px dashed #d1d8dd; }
	.iq-invoice .demo { margin-top: 18px; font-size: 0.8em; color: #6c7680; text-align: center; }
	.iq-invoice .meta { display: block; }
</style>

<div class="iq-invoice" dir="rtl" lang="ar">
	{%- if doc.docstatus == 2 %}<h4 class="text-center">ملغاة / CANCELLED</h4>{% endif -%}
	{%- if doc.docstatus == 0 %}<h4 class="text-center">مسودة / DRAFT</h4>{% endif -%}

	<h2>فاتورة ضريبية <span class="en">Tax Invoice</span></h2>
	<div class="subtitle">{{ doc.name }} &middot; {{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</div>

	<table class="parties">
		<tr>
			<td>
				<span class="ar">البائع</span><span class="en">Seller</span>
				<span class="meta">{{ company.get("company_name_in_arabic") or company.company_name }}</span>
				{%- if company.get("company_name_in_arabic") %}<span class="en">{{ company.company_name }}</span>{% endif -%}
				{%- if doc.company_address_display %}<span class="meta">{{ doc.company_address_display }}</span>{% endif -%}
				<span class="meta"><span class="ar">الرقم الضريبي الموحد:</span> <span dir="ltr">{{ company_tax_id or "—" }}</span></span>
				<span class="en">Unified Tax Number: {{ company_tax_id or "—" }}</span>
			</td>
			<td>
				<span class="ar">المشتري</span><span class="en">Buyer</span>
				<span class="meta">{{ doc.get("customer_name_in_arabic") or doc.customer_name }}</span>
				{%- if doc.get("customer_name_in_arabic") %}<span class="en">{{ doc.customer_name }}</span>{% endif -%}
				{%- if doc.address_display %}<span class="meta">{{ doc.address_display }}</span>{% endif -%}
				<span class="meta"><span class="ar">الرقم الضريبي الموحد:</span> <span dir="ltr">{{ customer_tax_id or "—" }}</span></span>
				<span class="en">Unified Tax Number: {{ customer_tax_id or "—" }}</span>
			</td>
		</tr>
		<tr>
			<td>
				<span class="ar">تاريخ الفاتورة:</span> <span dir="ltr">{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</span>
				<span class="en">Invoice Date</span>
			</td>
			<td>
				<span class="ar">تاريخ الاستحقاق:</span> <span dir="ltr">{{ frappe.format(doc.due_date, {"fieldtype": "Date"}) if doc.due_date else "—" }}</span>
				<span class="en">Due Date</span>
				<span class="meta"><span class="ar">العملة:</span> {{ doc.currency }} <span class="en">Currency</span></span>
			</td>
		</tr>
	</table>

	<table class="items">
		<thead>
			<tr>
				<th>#</th>
				<th>الصنف<span class="en">Item</span></th>
				<th class="num">الكمية<span class="en">Qty</span></th>
				<th class="num">السعر<span class="en">Rate</span></th>
				<th class="num">المبلغ<span class="en">Amount</span></th>
				{%- if has_item_tax %}
				<th class="num">نسبة الضريبة<span class="en">Tax Rate %</span></th>
				<th class="num">مبلغ الضريبة<span class="en">Tax Amount</span></th>
				<th class="num">الإجمالي<span class="en">Total</span></th>
				{%- endif %}
			</tr>
		</thead>
		<tbody>
			{%- for item in doc.items %}
			<tr>
				<td class="num">{{ loop.index }}</td>
				<td>{{ item.item_name }}{% if item.item_code and item.item_code != item.item_name %}<span class="en">{{ item.item_code }}</span>{% endif %}</td>
				<td class="num">{{ item.get_formatted("qty") }} {{ item.uom or "" }}</td>
				<td class="num">{{ money(item.net_rate) }}</td>
				<td class="num">{{ money(item.net_amount) }}</td>
				{%- if has_item_tax %}
				<td class="num">{{ frappe.utils.flt(item.get("tax_rate"), 2) }}%</td>
				<td class="num">{{ money(item.get("tax_amount")) }}</td>
				<td class="num">{{ money(item.get("total_amount")) }}</td>
				{%- endif %}
			</tr>
			{%- endfor %}
		</tbody>
	</table>

	{%- if doc.taxes %}
	<table class="taxes">
		<thead>
			<tr>
				<th>الضريبة / الرسم<span class="en">Tax / Charge</span></th>
				<th class="num">النسبة<span class="en">Rate %</span></th>
				<th class="num">المبلغ<span class="en">Amount</span></th>
			</tr>
		</thead>
		<tbody>
			{%- for tax in doc.taxes %}
			{%- if tax.tax_amount or print_settings.print_taxes_with_zero_amount %}
			<tr>
				<td>{{ tax.description }}</td>
				<td class="num">{{ tax.get_formatted("rate") }}</td>
				<td class="num">{{ money(tax.tax_amount) }}</td>
			</tr>
			{%- endif %}
			{%- endfor %}
		</tbody>
	</table>
	{%- endif %}

	<table class="totals">
		<tr>
			<td class="label">المجموع الفرعي <span class="en">Net Total</span></td>
			<td class="num">{{ money(doc.net_total) }}</td>
		</tr>
		{%- if doc.discount_amount %}
		<tr>
			<td class="label">الخصم <span class="en">Discount</span></td>
			<td class="num">{{ money(doc.discount_amount) }}</td>
		</tr>
		{%- endif %}
		<tr>
			<td class="label">مجموع الضرائب والرسوم <span class="en">Total Taxes and Charges</span></td>
			<td class="num">{{ money(doc.total_taxes_and_charges) }}</td>
		</tr>
		<tr class="grand">
			<td class="label">الإجمالي الكلي <span class="en">Grand Total</span></td>
			<td class="num">{{ money(doc.grand_total) }}</td>
		</tr>
		{%- if doc.rounded_total and doc.rounded_total != doc.grand_total %}
		<tr>
			<td class="label">الإجمالي المقرّب <span class="en">Rounded Total</span></td>
			<td class="num">{{ money(doc.rounded_total) }}</td>
		</tr>
		{%- endif %}
	</table>

	<div class="in-words">
		<span class="ar">المبلغ بالكلمات:</span> <span dir="ltr">{{ doc.in_words }}</span>
		<span class="en">Amount in words</span>
	</div>

	{%- if doc.terms %}
	<div class="terms" style="margin-top: 12px;">
		<span class="ar">الشروط والأحكام</span><span class="en">Terms and Conditions</span>
		{{ doc.terms }}
	</div>
	{%- endif %}

	<div class="demo">بيانات تجريبية - ليست وثيقة رسمية &middot; DEMO - not an official document</div>
</div>
